def validate_credit_card(number):
    def luhn_check(card_number):
        digits = [int(d) for d in str(card_number)]
        checksum = sum(digits[::-2] + [sum(divmod(d*2, 10)) for d in digits[-2::-2]])
        return checksum % 10 == 0
    return luhn_check(number)

