        if (resource != null) resource.close();
    } catch (Exception e) {
        logger.error("Error closing resource", e);
    }
}

public Integer parseIntSafe(String value) {
    try {
        return Integer.parseInt(value);
    } catch (NumberFormatException e) {
        return null;
    }
}

public void validateNotNull(Object obj, String fieldName) {
    if (obj == null) {
        throw new ValidationException(fieldName + " cannot be null");
    }
}

public CompletableFuture<String> handleTimeout(CompletableFuture<String> future, long timeout) {
    return future.orTimeout(timeout, TimeUnit.SECONDS)
        .exceptionally(ex -> "Default value");
}

