def versioned_api(route):
    @wraps(route)
    def wrapper(*args, **kwargs):
        version = request.headers.get('API-Version', 'v1')
        return route(*args, **kwargs, version=version)
    return wrapper

@app.errorhandler(404)
def not_found(error):
    return jsonify({'error': 'Not found', 'status': 404}), 404

def rate_limit_decorator(max_requests=100, window=3600):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            if not check_rate_limit(max_requests, window):
                abort(429)
            return f(*args, **kwargs)
        return wrapped
    return decorator

@app.route('/api/webhook', methods=['POST'])
def webhook():
    signature = request.headers.get('X-Signature')
    payload = request.get_data()
    if not verify_webhook_signature(payload, signature):
        abort(401)
    process_webhook(request.json)
    return '', 200

@RestController
@RequestMapping("/api/users")
public class UserController {
    @GetMapping
    public List<User> getAllUsers() {
        return userService.findAll();
    }
}

@PostMapping("/api/users")
public ResponseEntity<User> createUser(@RequestBody User user) {
    User created = userService.save(user);
    return ResponseEntity.status(201).body(created);
}

@GetMapping("/api/users/{id}")
public ResponseEntity<User> getUserById(@PathVariable Long id) {
    return userService.findById(id)
        .map(ResponseEntity::ok)
        .orElse(ResponseEntity.notFound().build());
}

@PutMapping("/api/users/{id}")
public ResponseEntity<User> updateUser(@PathVariable Long id, @RequestBody User user) {
    user.setId(id);
    return ResponseEntity.ok(userService.update(user));
}

@DeleteMapping("/api/users/{id}")
public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
    userService.delete(id);
    return ResponseEntity.noContent().build();
}

@GetMapping("/api/search")
public ResponseEntity<List<Result>> search(@RequestParam String q) {
    return ResponseEntity.ok(searchService.search(q));
}

@ExceptionHandler(MethodArgumentNotValidException.class)
public ResponseEntity<Map<String, String>> handleValidationExceptions(MethodArgumentNotValidException ex) {
    Map<String, String> errors = new HashMap<>();
    ex.getBindingResult().getFieldErrors().forEach(err -> errors.put(err.getField(), err.getDefaultMessage()));
    return ResponseEntity.badRequest().body(errors);
}

@GetMapping("/api/paginated")
public Page<Item> getPaginated(@RequestParam int page, @RequestParam int size) {
    return itemService.findAll(PageRequest.of(page, size));
}

